/**
 * testimonial — the home customer quote (prototype `.amag-quoteModul`; schema
 * `stardust/eds-schema/en-html.json` section 5). Template-slotted; one row, paragraphs read
 * in authored order: the first <p> is the quote (the live curly quotes are generated by CSS
 * around it, never authored), the next <p> the author, any further <p> the "customer of" line.
 * A <blockquote> is accepted for the quote as well. Unit hook: `amag-quoteModul`.
 */

function wrapNode(node, className) {
  const w = document.createElement('div');
  w.className = className;
  w.append(node);
  return w;
}

const el = (className) => {
  const d = document.createElement('div');
  d.className = className;
  return d;
};

function shell(block, name) {
  const wrapper = block.parentElement;
  if (!wrapper || !wrapper.classList.contains(`${name}-wrapper`)) return;
  wrapper.classList.add(`${name}-bleed-wrapper`);
  const section = block.closest('.section');
  if (!section) return;
  const sections = [...section.parentElement.children]
    .filter((s) => s.classList.contains('section') && s.children.length);
  if (sections[0] === section) block.classList.add('first-section');
  if (!wrapper.previousElementSibling) block.classList.add('band');
  if (!wrapper.nextElementSibling) block.classList.add('section-end');
}

export default function decorate(block) {
  const nodes = [...block.querySelectorAll('p, blockquote')]
    .filter((n) => !n.closest('blockquote p') && n.textContent.trim());
  if (!nodes.length) return;
  const wrap = el('wrap');
  const quote = el('quote amag-quoteModul');
  const [first, author, ...rest] = nodes;
  quote.append(wrapNode(first, 'quote-text'));
  if (author) quote.append(wrapNode(author, 'quote-author'));
  if (rest.length) {
    const by = el('quote-by');
    by.append(...rest);
    quote.append(by);
  }
  wrap.append(quote);
  block.replaceChildren(wrap);
  shell(block, 'testimonial');
}
